//! The generated files of a project: its build script, its launcher, the C
//! header replacements are written against, and the user templates.

use gex_abi::ctx;
use gex_native::aot::{REPL_BASE, REPL_DATA_BYTES};

/// `build.sh`: the reproducible build step.
pub fn build_sh() -> String {
    format!(
        r#"#!/bin/sh
# Build this ejected project. Generated by `gexc eject`; a re-eject rewrites it.
#
#   1. user/src/*.c -> build/user.wasm: your replacement functions, compiled
#      with clang for wasm32 against the guest's memory (see gen/gex_replace.h).
#   2. runtime/gexc eject build: translate the program's objects into
#      build/modules, check every replacement in user/eject.json against the
#      objects' hashes and symbols, and assemble build/rootfs (rootfs/ plus
#      user/files/), and with a browser runtime (runtime/web), the web build
#      in build/web for run.mjs and index.html.
#
# Environment: CLANG, WASM_LD (default clang, wasm-ld), USER_CFLAGS, USER_LDFLAGS
# (wasm-ld flags).
set -eu
HERE=$(cd "$(dirname "$0")" && pwd)
mkdir -p "$HERE/build"
set -- "$HERE"/user/src/*.c
rm -f "$HERE/build/user.wasm" "$HERE/build/user.web.wasm"
if [ -e "$1" ]; then
    # Compiled as the function tier compiles its C (gexc eject decompile
    # writes that C), with every function exported.
    rm -rf "$HERE/build/obj" && mkdir -p "$HERE/build/obj"
    for c in "$@"; do
        ${{CLANG:-clang}} {cflags} -fvisibility=default -I"$HERE/gen" ${{USER_CFLAGS:-}} \
            -c "$c" -o "$HERE/build/obj/$(basename "$c" .c).o"
    done
    # Replacement code shares the guest's memory: its data and heap go at
    # {base:#x} (above everything the guest and the runtime use; {data} MiB),
    # and the runtime gives each guest thread its own stack after them.
    LINK="--no-entry --export-dynamic --import-memory --max-memory={max} --global-base={base} \
        --export=__stack_pointer --export=__heap_base ${{USER_LDFLAGS:-}}"
    ${{WASM_LD:-wasm-ld}} $LINK --shared-memory -o "$HERE/build/user.wasm" "$HERE"/build/obj/*.o
    # And for the browser's single-Worker shim, whose memory is not shared.
    if [ -e "$HERE/runtime/web/gex_browser.wasm" ]; then
        ${{WASM_LD:-wasm-ld}} $LINK -o "$HERE/build/user.web.wasm" "$HERE"/build/obj/*.o
    fi
fi
exec "$HERE/runtime/gexc" eject build "$HERE"
"#,
        base = REPL_BASE,
        data = REPL_DATA_BYTES >> 20,
        max = gex_abi::GUEST_MEM_BYTES,
        cflags = gex_cgen::toolchain::CFLAGS.join(" "),
    )
}

/// `run.sh`: the native launcher.
pub fn run_sh() -> String {
    r#"#!/bin/sh
# Run this ejected project natively (wasmtime). Generated by `gexc eject`.
#
#   ./run.sh                 the recorded arguments (or user/eject.json's "args")
#   ./run.sh ARGS...         these arguments instead (after argv[0])
#   ./run.sh --jit-fallback -- ARGS...
#                            translate code the build never saw instead of
#                            failing on it (off by default)
#   ./run.sh --strace -- ARGS...   trace system calls
HERE=$(cd "$(dirname "$0")" && pwd)
exec "$HERE/runtime/gexc" eject run "$HERE" "$@"
"#
    .to_string()
}

pub const GITIGNORE: &str = "build/\n";

/// `gen/gex_replace.h`: what a replacement function needs to know about the
/// guest. Specific to the project's ISA.
pub fn header(isa: &str) -> String {
    let (ints, ret, sp, stack_note, stack_first): (&[u8], u8, usize, &str, u32) = if gex_abi::X86 {
        (
            &[7, 6, 2, 1, 8, 9],
            0,
            ctx::x(4),
            "the 7th integer argument is at [rsp + 8]: the return address is at [rsp]",
            8,
        )
    } else {
        (&[0, 1, 2, 3, 4, 5, 6, 7], 0, ctx::SP, "the 9th integer argument is at [sp]", 0)
    };
    let ints = ints.iter().map(|r| r.to_string()).collect::<Vec<_>>().join(", ");
    format!(
        r#"/* Generated by `gexc eject` for an {isa} guest; a re-eject rewrites it.
 *
 * Replacement functions run as wasm32 code in the guest's own memory, where a
 * guest address is a linear-memory offset: a guest pointer is a C pointer.
 *
 * Two ABIs (user/eject.json "abi"):
 *
 *   "c" (default): an ordinary C function. The runtime passes the guest's
 *       integer argument registers in order to its i32/i64 parameters and its
 *       floating-point argument registers to its f32/f64 ones, and puts the
 *       result in the guest's return register. Pointers arrive as i32.
 *
 *       int64_t my_strlen(const char *s) {{ ... }}
 *
 *   "ctx": void f(gex_ctx ctx). The function reads and writes the guest's
 *       registers through the context itself (stack arguments, structs,
 *       several results). It must not return for the guest: the runtime does
 *       that after it.
 *
 *       void my_fn(gex_ctx c) {{ GEX_RET(c) = GEX_ARG(c, 0) + 1; }}
 *
 * Export the function (any non-static function is, with build.sh's
 * --export-dynamic) and name it in user/eject.json.
 */
#ifndef GEX_REPLACE_H
#define GEX_REPLACE_H
#include <stdint.h>

/* The guest context of the calling thread: its guest address. */
typedef uint32_t gex_ctx;

#define GEX_ISA "{isa}"
#define GEX_PTR(guest_addr) ((void *)(uintptr_t)(uint32_t)(guest_addr))
#define GEX_X(c, n) (*(uint64_t *)GEX_PTR((c) + {x0} + 8u * (n)))
static const uint8_t gex_int_arg_regs[] = {{{ints}}};
/* The i-th integer argument, and the integer return register. */
#define GEX_ARG(c, i) GEX_X((c), gex_int_arg_regs[(i)])
#define GEX_RET(c) GEX_X((c), {ret})
/* The i-th floating-point argument register (low lane), and the return. */
#define GEX_FARG_F64(c, i) (*(double *)GEX_PTR((c) + {v0} + 16u * (i)))
#define GEX_FARG_F32(c, i) (*(float *)GEX_PTR((c) + {v0} + 16u * (i)))
#define GEX_FRET_F64(c) GEX_FARG_F64((c), 0)
#define GEX_FRET_F32(c) GEX_FARG_F32((c), 0)
/* The stack pointer. Stack arguments: {stack_note}. */
#define GEX_SP(c) (*(uint64_t *)GEX_PTR((c) + {sp}))
#define GEX_STACK_ARG(c, i) (*(uint64_t *)GEX_PTR(GEX_SP(c) + {stack_first}u + 8u * (i)))

#endif
"#,
        x0 = ctx::x(0),
        v0 = ctx::v(0),
    )
}

pub const USER_README: &str = "\
Your part of an ejected project. `gexc eject` creates this directory once\n\
and never writes to it again, so a re-eject keeps everything here.\n\
\n\
  eject.json   settings: library replacements, coverage, default arguments\n\
  src/*.c      replacement functions; build.sh compiles them into\n\
               build/user.wasm (see ../gen/gex_replace.h)\n\
  files/       added to the guest's filesystem at build time, at the same\n\
               path under / (files/etc/foo.conf is /etc/foo.conf), over the\n\
               files the recorded session read\n";
